import {supabase,currentUser,login} from './auth-client.mjs';
import {validateSubmission,availability} from './admin-model.mjs';
const $=id=>document.getElementById(id),el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
let crops=[],rows=[],busy=false;
async function rpc(name,args={}){const {data,error}=await supabase.rpc(name,args);if(error)throw Error(error.message);return data;}
function status(text){$('farm-status').textContent=text;}
function render(){const selected=Number($('farm-crop').value);$('farm-list').replaceChildren(...rows.filter(r=>r.crop_id===selected&&Number(r.exhausted)<3).map(r=>{const card=el('article');card.className='admin-queue-row';card.append(el('strong','+'+r.bonus+'% · '+crops.find(c=>c.id===r.crop_id)?.support),el('p',availability(r)+' · '+r.reveals+' UID reveals · '+r.exhausted+' exhaustion reports'));const reveal=el('button','Reveal UID');reveal.type='button';reveal.onclick=async()=>{reveal.disabled=true;try{const uid=await rpc('reveal_farm_support',{p_id:r.id});card.querySelector('.revealed')?.remove();const displayed=el('p','UID '+uid);displayed.className='revealed';card.append(displayed);const copy=el('button','Copy UID');copy.type='button';copy.onclick=()=>navigator.clipboard.writeText(uid).then(()=>status('UID copied.')).catch(()=>status('Select the displayed UID to copy it.'));displayed.append(copy);await reload(false);}catch(e){status(e.message);}finally{reveal.disabled=false;}};card.append(reveal);for(const [title,value] of [['Support worked','worked'],['Report exhausted','exhausted']]){const button=el('button',title);button.type='button';button.onclick=async()=>{button.disabled=true;try{await rpc('report_farm_support',{p_id:r.id,p_report:value});await reload();status('Report saved for this 12-hour round.');}catch(e){status(e.message);}finally{button.disabled=false;}};card.append(button);}return card;}));if(!$('farm-list').children.length)$('farm-list').append(el('p','No available approved listings for this crop yet.'));}
async function reload(paint=true){rows=await rpc('farm_support_directory');if(paint)render();const requests=await rpc('my_farm_support_requests');$('my-submissions').replaceChildren(...requests.map(r=>el('li','UID '+r.game_uid+' · '+crops.find(c=>c.id===r.crop_id)?.name+' · +'+r.bonus+'% · '+r.status+(r.review_note?' · '+r.review_note:''))));}
async function gate(){const user=await currentUser();$('farm-tools').hidden=!user;$('farm-gate').hidden=!!user;if(user)try{await reload();status('Only admin-approved UIDs are listed.');}catch(e){status('Directory setup is not active yet. '+e.message);}}
$('farm-login').onclick=()=>login('discord').catch(e=>status(e.message));$('farm-crop').onchange=render;
$('farm-submit').onsubmit=async e=>{e.preventDefault();if(busy)return;try{const v=validateSubmission({uid:$('submit-uid').value.trim(),crop:Number($('submit-crop').value),bonus:Number($('submit-bonus').value),permission:$('submit-permission').checked,note:$('submit-note').value});busy=true;$('submit-button').disabled=true;await rpc('submit_farm_support',{p_uid:v.uid,p_crop:v.crop,p_bonus:v.bonus,p_permission:v.permission,p_note:v.note});$('farm-submit').reset();await reload();status('Submitted for administrator review. It is not public yet.');}catch(error){status(error.message);}finally{busy=false;$('submit-button').disabled=false;}};
try{const response=await fetch(new URL('./guide-data/cozy-farm.json',import.meta.url));if(!response.ok)throw Error('Crop data unavailable');crops=(await response.json()).crops;for(const id of ['farm-crop','submit-crop'])$(id).replaceChildren(...crops.map(c=>{const o=el('option',c.name+' · '+c.support);o.value=c.id;return o;}));await gate();}catch(e){status(e.message);}
supabase.auth.onAuthStateChange(()=>setTimeout(()=>gate().catch(e=>status(e.message)),0));
